const KEYS={products:'ym_demo_products',cart:'ym_demo_cart',wish:'ym_demo_wishlist',orders:'ym_demo_orders',coupon:'ym_demo_coupon',lastOrder:'ym_demo_last_order',theme:'yviora_theme'};
try{if(localStorage.getItem('yviora_catalog_v3')!=='done'){[KEYS.products,KEYS.cart,KEYS.wish,KEYS.coupon].forEach(key=>localStorage.removeItem(key));localStorage.setItem('yviora_catalog_v3','done')}}catch{}
const read=(key,fallback)=>{try{const value=JSON.parse(localStorage.getItem(key));return value===null?fallback:value}catch{return fallback}};
let products=read(KEYS.products,DEFAULT_PRODUCTS);
let cart=read(KEYS.cart,[]);
let wishlist=read(KEYS.wish,[]);
let activeCoupon=read(KEYS.coupon,'');
let currentRoute=null;
let toastTimer;
const app=document.getElementById('app');
const footer=document.getElementById('site-footer');
const php=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:0}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>products.find(p=>p.id===id);
const persist=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
function applyTheme(){const theme=read(KEYS.theme,'light')==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;const toggle=document.getElementById('theme-toggle');if(toggle){toggle.textContent=theme==='dark'?'☼':'☾';toggle.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');toggle.setAttribute('aria-pressed',String(theme==='dark'))}}
function toggleTheme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';persist(KEYS.theme,next);applyTheme()}
function inventory(){return cart.reduce((n,row)=>n+(Number(row.qty)||0),0)}
function updateCartCount(){document.getElementById('cart-count').textContent=inventory()}
function toast(message){const region=document.getElementById('toast-region');region.innerHTML=`<div class="toast" role="status">${esc(message)} <button aria-label="Dismiss notification" data-action="dismiss-toast">×</button></div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>region.innerHTML='',3500)}
function categoryName(slug){return({jewelry:'Jewelry & Accessories',bags:'Bags & Everyday',cute:'Cute Finds',lifestyle:'Lifestyle & Random Finds',caps:'Caps & Hats'})[slug]||'All Finds'}
function productCard(p){
  const liked=wishlist.includes(p.id), purchasable=Number(p.price)>0&&p.stock>0;
  const price=Number(p.price)>0?php(p.price):'Price coming soon';
  const action=purchasable?'Add to bag · '+php(p.price):'Coming soon';
  return `<article class="product-card"><div class="product-image-wrap"><a href="#/product/${encodeURIComponent(p.id)}" aria-label="View ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"></a>${p.badge?`<span class="product-badge">${esc(p.badge)}</span>`:''}<button class="wish-button ${liked?'active':''}" data-action="wishlist" data-id="${esc(p.id)}" aria-label="${liked?'Remove from':'Add to'} wishlist" aria-pressed="${liked}">${liked?'♥':'♡'}</button><div class="quick-add"><button class="button" data-action="quick-add" data-id="${esc(p.id)}" ${purchasable?'':'disabled'}>${action}</button></div></div><div class="product-meta"><span class="product-category">${esc(p.type)}</span><a class="product-name" href="#/product/${encodeURIComponent(p.id)}">${esc(p.name)}</a><div class="product-price">${price}${p.was?` <del>${php(p.was)}</del>`:''}</div><span class="demo-tag">Price and availability coming soon</span></div></article>`;
}
function cards(items){return `<div class="product-grid">${items.map(productCard).join('')}</div>`}
function categoryCards(){
  const cats=[
    ['jewelry','Jewelry & Accessories','Little details, lovely shine.','✧','category-jewelry'],
    ['bags','Bags & Everyday','Your everyday, a little sweeter.','♡','category-bags'],
    ['cute','Cute Finds','Tiny treasures, big smiles.','✿','category-cute'],
    ['lifestyle','Lifestyle Finds','Useful things and happy surprises.','☾','category-lifestyle'],
    ['caps','Caps & Hats','Everyday caps with playful details.','◒','category-bags']
  ];
  return '<div class="category-grid">'+cats.map(([slug,title,desc,icon,style])=>'<a class="category-card no-image '+style+'" href="#/shop?category='+slug+'"><span class="category-symbol" aria-hidden="true">'+icon+'</span><div class="category-card-copy"><small>Explore the collection</small><h3>'+title+'</h3><span>'+desc+' &nbsp;↗</span></div></a>').join('')+'</div>';
}
function trustStrip(){
  return '<section class="trust-strip" aria-label="About Yviora"><div class="trust-items"><div class="trust-item"><span class="trust-icon">♡</span><div><strong>Affordable finds</strong><small>Lovely prices for little joys</small></div></div><div class="trust-item"><span class="trust-icon">✧</span><div><strong>Thoughtfully picked</strong><small>A curated mix of favorites</small></div></div><div class="trust-item"><span class="trust-icon">⌕</span><div><strong>Easy online browsing</strong><small>Shop at your own pace</small></div></div><div class="trust-item"><span class="trust-icon">☏</span><div><strong>Friendly support</strong><small>Reach us through the contact form</small></div></div></div></section>';
}
